begin;
select no_plan();
select ok(not has_function_privilege('authenticated','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Browser cannot spoof gateway subject');
select ok(not has_function_privilege('anon','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Anonymous cannot call layout gateway');
select ok(has_function_privilege('service_role','api.execute_owner_profile_editor_server(uuid,text,jsonb)','EXECUTE'),'Server gateway available');
select ok(not has_function_privilege('service_role','api.save_current_owner_block_link_working(jsonb)','EXECUTE'),'Original layout RPC remains private');
insert into auth.users(id,email) values('26300000-0000-4000-8000-000000000001','link-gateway-one@example.test'),('26300000-0000-4000-8000-000000000002','link-gateway-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('26300000-0000-4000-8000-000000000001','26300000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'link263-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Source Profile','Retained Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
insert into core.identity_block_collections_working(owner_id) select owner_id from actors;
insert into core.identity_blocks_working(block_id,owner_id,kind,position,is_visible)
 select '26300000-0000-4000-8000-000000000011',owner_id,'generic_link',1,false from actors where auth_user_id='26300000-0000-4000-8000-000000000001';
insert into core.identity_blocks_working(block_id,owner_id,kind,position)
 select '26300000-0000-4000-8000-000000000012',owner_id,'social',2 from actors where auth_user_id='26300000-0000-4000-8000-000000000001';
insert into core.identity_blocks_working(block_id,owner_id,kind,position)
 select '26300000-0000-4000-8000-000000000014',owner_id,'generic_link',1 from actors where auth_user_id='26300000-0000-4000-8000-000000000002';
set local request.jwt.claims='{"role":"service_role","sub":"26300000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='26300000-0000-4000-8000-000000000002';
create function pg_temp.save_link(target uuid,base bigint,kind text) returns jsonb language sql as $$select api.execute_owner_profile_editor_server('26300000-0000-4000-8000-000000000001','save_current_owner_block_link_working',jsonb_build_object('input_working',jsonb_build_object('block_id',target,'base_collection_revision',base,'link_working',jsonb_build_object('kind',kind,'title',' Raw <em>unfinished</em> ','social_platform',null,'destination_url','javascript:unfinished'))));$$;
grant execute on function pg_temp.save_link(uuid,bigint,text) to service_role;
set local role service_role;
select is(pg_temp.save_link('26300000-0000-4000-8000-000000000011',1,'generic_link'),'{"status":"success","block_id":"26300000-0000-4000-8000-000000000011","collection_revision":2}'::jsonb,'Real gateway persists unfinished own link and exact revision');
select is(current_setting('request.jwt.claim.sub'),'26300000-0000-4000-8000-000000000002','Outer subject restored');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"26300000-0000-4000-8000-000000000002"}'::jsonb,'Outer claims restored');
select is(pg_temp.save_link('26300000-0000-4000-8000-000000000011',1,'generic_link')->>'status','stale_write','Duplicate CAS rejected');
select is(pg_temp.save_link('26300000-0000-4000-8000-000000000014',2,'generic_link')->>'status','block_not_found','Foreign block rejected through actual Owner predicate');
select is(pg_temp.save_link('26300000-0000-4000-8000-000000000012',2,'generic_link')->>'status','invalid_link_working','Caller kind cannot change real member kind');
select is(pg_temp.save_link('26300000-0000-4000-8000-000000000012',2,'social')->>'status','success','Sibling accepts next acknowledged collection base');
select is(api.execute_owner_profile_editor_server('26300000-0000-4000-8000-000000000001','save_current_owner_block_link_working','{"input_working":{},"owner_id":"26300000-0000-4000-8000-000000000002"}')->>'status','unavailable','Outer caller authority denied');
reset role;
select is((select title from core.identity_block_links_working where block_id='26300000-0000-4000-8000-000000000011'),' Raw <em>unfinished</em> ','Raw text preserved exactly');
select is((select destination_url from core.identity_block_links_working where block_id='26300000-0000-4000-8000-000000000011'),'javascript:unfinished','Unfinished URL remains private Working');
select is((select is_visible from core.identity_blocks_working where block_id='26300000-0000-4000-8000-000000000011'),false,'Hidden membership not restored');
select is((select count(*)::int from core.identity_block_links_working where owner_id=(select owner_id from actors where auth_user_id='26300000-0000-4000-8000-000000000002')),0,'Foreign Owner payload untouched');
select ok(not exists(select 1 from core.identity_publications where snapshot<>'{"legacy":true}'::jsonb),'Published snapshots unchanged');
select ok(not exists(select 1 from core.identity_working where owner_id in(select owner_id from actors) and (display_name<>'Source Profile' or revision<>2)),'Profile revision preserved');
create function pg_temp.reject_link_update() returns trigger language plpgsql as $$begin raise exception 'fixture link write failure';end;$$;
create trigger link_editor_fixture before update on core.identity_block_links_working for each row execute function pg_temp.reject_link_update();
set local role service_role;
select throws_ok($q$select pg_temp.save_link('26300000-0000-4000-8000-000000000011',3,'generic_link')$q$,'P0001','fixture link write failure','Actual write exception propagates');
select is(current_setting('request.jwt.claim.sub'),'26300000-0000-4000-8000-000000000002','Exception restores subject');
reset role;
drop trigger link_editor_fixture on core.identity_block_links_working;
update core.owners set account_state='restricted' where id in(select owner_id from actors);
set local role service_role;
select is(pg_temp.save_link('26300000-0000-4000-8000-000000000011',3,'generic_link')->>'status','owner_not_eligible','Restriction prevents write');
reset role;
select * from finish();
rollback;
